@@ -0,0 +1,20 @@
+import { createEventCard } from './event-card.js';
+import { sortByStart } from './agenda.js';
+import { summarizeAttendance } from './attendance.js';
+
+function signupsFor(signupsByEvent, id) {
+  if (signupsByEvent instanceof Map) {
+    return signupsByEvent.get(id) ?? [];
+  }
+  if (signupsByEvent && Object.hasOwn(signupsByEvent, id)) {
+    return signupsByEvent[id] ?? [];
+  }
+  return [];
+}
+
+export function buildOrganizerDigest(events, signupsByEvent = {}) {
+  return sortByStart(events, (event) => {
+    const card = createEventCard(event);
+    return { ...card, ...summarizeAttendance(event, signupsFor(signupsByEvent, card.id)) };
+  });
+}

